/// Prefix of the browser-session bridge: `/ui/api/v1/...` mirrors the main
/// `/api/v1` group with session authentication (like upstream's `/canvas/api`).
pub const UI_PREFIX: &str = "ui/";

fn spec(method: &str, uri: &str) -> &'static RouteSpec {
    ROUTES
        .iter()
        .find(|s| s.method == method && s.uri == uri)
        .unwrap_or_else(|| panic!("route {method} {uri} missing from ROUTES"))
}

